package edu.uao.yugioh.model; import java.util.*; public class Jugador { public static final int LP_INICIALES=8000; private final String nombre; private int lp; private final List<Monstruo> campo=new ArrayList<>(); public Jugador(String n){this(n,LP_INICIALES);} public Jugador(String n,int lpInicial){if(n==null||n.isBlank()||lpInicial<0)throw new IllegalArgumentException();nombre=n;lp=lpInicial;} public String getNombre(){return nombre;} public int getLp(){return lp;} public List<Monstruo> getCampo(){return Collections.unmodifiableList(campo);} public void agregarMonstruo(Monstruo m){campo.add(Objects.requireNonNull(m));} public void recibirDano(int dano){if(dano<0)throw new IllegalArgumentException();lp=Math.max(0,lp-dano);} public boolean estaDerrotado(){return lp==0;} }